import Foundation

/// The list of downloadable packages, published next to the packages (`content/packages/manifest.json`,
/// generated by `tools/content/build_download_packages.py`).
struct ContentManifest: Codable, Equatable, Sendable {
    static let supportedManifestVersion = 1

    let manifestVersion: Int
    let packages: [ManifestEntry]

    /// Decodes and validates; entries that fail validation make the whole manifest invalid.
    static func decode(_ data: Data) throws(AppError) -> ContentManifest {
        let manifest: ContentManifest
        do {
            manifest = try JSONDecoder().decode(ContentManifest.self, from: data)
        } catch {
            throw .contentCorrupted("manifest: \(error)")
        }
        guard manifest.manifestVersion == supportedManifestVersion else {
            throw .contentCorrupted("Unsupported manifest version \(manifest.manifestVersion)")
        }
        for entry in manifest.packages { try entry.validate() }
        guard Set(manifest.packages.map(\.id)).count == manifest.packages.count else {
            throw .contentCorrupted("Duplicate package IDs in manifest")
        }
        return manifest
    }
}

/// One package: §10's collection identifier, version, language, file size, source, license, checksum and
/// schema version, plus display and location fields.
struct ManifestEntry: Codable, Equatable, Hashable, Sendable, Identifiable {
    static let maximumFileSize = 50 * 1024 * 1024

    let id: String
    let collectionID: String
    let title: String
    let version: Int
    let languages: [String]
    let fileSize: Int
    let sources: [String]
    let license: String
    /// Lowercase hex SHA-256 of the package file.
    let sha256: String
    let schemaVersion: Int
    let passageCount: Int
    /// Location relative to the manifest URL.
    let path: String

    func validate() throws(AppError) {
        let slug = /[a-z0-9][a-z0-9.-]{0,63}/
        guard id.wholeMatch(of: slug) != nil, collectionID.wholeMatch(of: slug) != nil else {
            throw .contentCorrupted("Invalid package identifier \(id)")
        }
        guard sha256.wholeMatch(of: /[0-9a-f]{64}/) != nil else { throw .contentCorrupted("\(id): invalid checksum") }
        guard (1...Self.maximumFileSize).contains(fileSize) else { throw .contentCorrupted("\(id): invalid size") }
        guard SampleLibraryDTO.supportedSchemaVersions.contains(schemaVersion) else {
            throw .contentCorrupted("\(id): unsupported schema \(schemaVersion)")
        }
        guard version > 0, !path.isEmpty, !path.contains(".."), !path.hasPrefix("/"), !path.contains("://") else {
            throw .contentCorrupted("\(id): invalid version or path")
        }
    }

    /// The package's URL, resolved against the manifest's location.
    func url(relativeTo manifestURL: URL) -> URL {
        URL(filePath: path, relativeTo: manifestURL.deletingLastPathComponent()).absoluteURL
    }
}
